"""Typed builders. Generated by `python -m ekbatan.codegen n2pkg.sub_model`.

Regenerate this when a model gains or loses a field. A stale builder is a type error
rather than a wrong answer: build() calls the real constructor, which will refuse.
"""

from __future__ import annotations

from decimal import Decimal
from ekbatan.domain import ModelBuilder
from typing import Self, TYPE_CHECKING
from uuid import UUID

if TYPE_CHECKING:
    from ekbatan.domain import GenericState  # noqa: F401
    from ekbatan.ids import Id  # noqa: F401
    from .model import Wallet  # noqa: F401
    from .sub_model import SavingsWallet  # noqa: F401

class SavingsWalletBuilder(ModelBuilder["SavingsWallet", "Id[Wallet]", "GenericState"]):
    """Builds a SavingsWallet, with the field types a checker can see.

    id, state, version and the timestamps come from ModelBuilder, typed by the
    parameters above, so only the fields SavingsWallet added are declared here.
    """

    builds_ref = "n2pkg.sub_model:SavingsWallet"

    def owner_id(self, value: UUID) -> Self:
        return self.set(owner_id=value)

    def balance(self, value: Decimal) -> Self:
        return self.set(balance=value)

    def memo(self, value: str | None) -> Self:
        return self.set(memo=value)

    def kind(self, value: Any[Any, Any]) -> Self:
        return self.set(kind=value)

    def limits(self, value: tuple[int, Any]) -> Self:
        return self.set(limits=value)

    def label(self, value: str) -> Self:
        return self.set(label=value)

    def rate(self, value: int) -> Self:
        return self.set(rate=value)

def savings_wallet(source: SavingsWallet | None = None) -> SavingsWalletBuilder:
    """A fresh SavingsWalletBuilder, optionally pre-loaded from an existing SavingsWallet."""
    made = SavingsWalletBuilder()
    return made.copy_base(source) if source is not None else made
